        margin-left: 3vw;
        height: 100%;
        color: white !important;
    }
    .student{
        text-decoration:none !important;
        color: black !important;
    }
    .already{
        text-decoration:none !important;
        color: black !important;
    }
    .first_name{
        width: 100%;
    }
    .last_name{
        width: 100%;
    }
    @media only screen and (max-width: 600px) {
        .about_title{
            font-size: 4vw;
        }
        .about_text{
            font-size: 3vw;
        }
        .about_btn{
            width: 55%;
